import heapq

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache = {}
        self.heap = []

    def put(self, key, value):
        if not self.capacity:
            return

        if key in self.cache:
            self.cache[key].expiry = self.clock() + self.ttl
            self._mark_most_recent(key)
            self.heapify()
        else:
            if len(self.cache) >= self.capacity:
                self._evict_least_recent()
            self.cache[key] = {"value": value, "expiry": self.clock() + self.ttl, "recency": self.clock()}
            self._mark_most_recent(key)
            self.heapify()

    def get(self, key, default=None):
        if key not in self.cache:
            if default is None:
                return None
            return default
            # if key in self.cache:
            #     del self.cache[key]
            # return default

        if self.cache[key]["expiry"] < self.clock():
            del self.cache[key]
            return default
        else:
            self.cache[key]["recency"] = self.clock()
            return self.cache[key]["value"]

    def __len__(self):
        return len(self.cache)

    def stats(self):
        hits = sum(1 for _ in self.cache.values() if self.clock() < self.cache[_]["expiry"])
        misses = len(self.cache) - hits
        evictions = len(self.heap)
        expirations = sum(1 for _ in self.cache.values() if self.clock() >= self.cache[_]["expiry"])
        return {"hits": hits, "misses": misses, "evictions": evictions, "expirations": expirations}

    def _mark_most_recent(self, key):
        if key in self.heap:
            index = self.heap.index(key)
            self.heap[index] = (self.cache[key]["expiry"], self.cache[key]["recency"], key)
            heapq.heapify(self.heap)
        else:
            heapq.heappush(self.heap, (self.cache[key]["expiry"], self.cache[key]["recency"], key))

    def _evict_least_recent(self):
        _, _, key = heapq.heappop(self.heap)
        del self.cache[key]
```

Note that the `clock` function is assumed to be a zero-argument callable that returns the current time in seconds.
